package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.yaml.snakeyaml.LoaderOptions;
import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.SafeConstructor;
import static org.jlinalg.cli.SeuratDifferentialContracts.*;
import static org.jlinalg.cli.SignacPeaksContracts.*;
import static org.jlinalg.cli.SignacPeaksContracts.validate;

/** Typed original MACS peak calls with native Signac preparation/transport/reduction. */
public final class SignacPeaksCli {
    private SignacPeaksCli() { }
    static final String ACTION="Read WARNINGS.md, analysis-status.json, diagnostics.json, prepared-summary.json and raw source process logs/results. Preserve all attempts. SKIP3 means a required permitted exact Linux MACS/Python runtime is unavailable: provide the named private profile where permitted; otherwise skip dependent peak analysis. FAIL2 admits no result, including retained partial tables. Correct the named input/group/map/format/source/runtime/process/capacity cause and retry into NEW output paths. No analysis-time installation, alternative peak caller, coordinate/identity repair or inferred paper settings occur. Review all source warnings, duplicate policy, effective genome size and BED/BEDPE semantics. VERIFY checks capture/native geometry and reduction consistency, not independent MACS statistical replay, full host/DLL authenticity or biological validity.";
    static final String SCOPE="DEVELOPMENT_SCOPE: original exact MACS2 calls through retained Signac1.9/1.14 command semantics, explicit fragment populations and native Linux splitting/Seqinfo1.2/GenomicRanges1.64 geometry. Genome build is a declaration; source result sequence metadata remains unknown. Safe indexed file prefixes are explicit transport; original/source-normalized labels remain recorded. Broader Signac workflows, historical whole environments, biological/full-paper reproduction and coordinated-capture authenticity are not certified.";
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    static int run(String[] args,PrintStream out,PrintStream err) {
        try {
            if(args.length==1&&args[0].equals("--help")){emit(out,"SignacPeaksCli --request UTF8_JSON\nModes: POOLED (all supplied fragment rows), GROUPED (declared cell/map populations), VERIFY (Java only).\nUse NEW outputs. Relative paths resolve against the JSON directory. Original calling requires Linux Java, including WSL on Windows.\n"+SCOPE+"\n"+ACTION);return 0;}
            if(args.length!=2||!args[0].equals("--request"))throw new IOException("Require --request UTF8_JSON or --help");Path requestPath=Path.of(args[1]).toAbsolutePath().normalize();Map<String,Object> raw=read(requestPath);
            if("VERIFY".equals(raw.get("mode"))){keys(raw,Set.of("schema_version","mode","analysis"));if(integer(raw,"schema_version",0,1,1)!=1)throw new IOException("Require schema_version1");verify(resolve(requestPath.getParent(),text(raw,"analysis")));emit(out,"Verified original MACS capture and native peak geometry/reduction consistency. "+ACTION);return 0;}
            Map<String,Object> r=validate(raw);byte[] source=Files.readAllBytes(requestPath);String sourceHash=SignacPeaksRuntime.sha(source);Path destination=resolve(requestPath.getParent(),text(r,"out"));int[] code={0};
            FollowupSupport.externalTransaction(Map.of("out",destination.toString()),"original-MACS2-Signac-peak-calling-development",(stage,manifest)->{
                Map<String,Object> state=new LinkedHashMap<>();state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("results_admitted",false);List<String> warnings=new ArrayList<>(List.of(SCOPE));
                try {
                    if(!sourceHash.equals(FollowupSupport.hash(requestPath)))throw new IOException("Original peak request changed before capture");Files.write(stage.resolve("source-request.json"),source,StandardOpenOption.CREATE_NEW);var captured=SignacPeaksInputs.capturedRequest(raw);var inputs=SignacPeaksInputs.capture(raw,captured,requestPath.getParent(),stage,value(r,"maximum_input_bytes"));json(stage.resolve("request.json"),captured);var effective=validate(captured);json(stage.resolve("effective-request.json"),effective);
                    SignacPeaksRuntime.sources(stage,false);var prepared=SignacPeaksInputs.prepare(stage,effective,false);warnings.addAll(prepared.warnings());Files.createDirectory(stage.resolve("process"));Files.createDirectory(stage.resolve("macs"));
                    RsemProcess.Check integrity=()->{for(var e:inputs.entrySet())if(!e.getValue().equals(FollowupSupport.hash(stage.resolve(e.getKey()))))throw new IOException("Captured original fragment/map input changed");SignacPeaksRuntime.sources(stage,true);};
                    var bound=SignacPeaksRuntime.bind(stage,requestPath.getParent(),r,integrity);
                    for(var job:prepared.jobs()){List<String> paths=job.inputs().stream().map(p->stage.resolve(p).toString()).toList();SignacPeaksRuntime.execute(stage,bound,r,paths,job.id(),integrity);}
                    integrity.verify();SignacPeaksInputs.prepare(stage,effective,true);warnings.addAll(SignacPeaksOutputs.publish(stage,effective,prepared,bound.home().toString(),stage.toString(),false));
                    state.put("status","completed-with-warnings");state.put("results_admitted",true);state.put("all_requested_calls_completed",true);state.put("requested_calls",prepared.jobs().size());
                    manifest.put("source_request_sha256",sourceHash);manifest.put("captured_input_sha256",inputs);manifest.put("request_directory_at_execution",requestPath.getParent().toString());manifest.put("stage_at_execution",stage.toString());
                    json(stage.resolve("COMPLETED.json"),Map.of("schema_version",1,"engine",ENGINE,"status","completed-audited-original-peak-capture","results_admitted",true,"statistical_replay",false,"authentication",false));
                } catch(SignacPeaksRuntime.Unavailable|RsemProcess.UnavailableDependency failure){code[0]=3;state.put("status","SKIP3_DEPENDENT_PEAK_ANALYSIS_SKIPPED");state.put("results_admitted",false);state.put("error",failure.toString());warnings.add("SKIP3: "+failure+". Dependent peak analysis was skipped; no result admitted.");}
                catch(Exception failure){code[0]=2;state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("results_admitted",false);state.put("error",failure.toString());warnings.add("FAIL2: "+failure+". Any partial tables remain retained evidence, not admitted results.");}
                catch(OutOfMemoryError failure){code[0]=2;state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("results_admitted",false);state.put("error","Java heap exhausted");warnings.add("FAIL2: Java heap exhausted; use suitable explicit capacities/heap and NEW outputs. No partial result admitted.");}
                state.put("required_action",ACTION);json(stage.resolve("analysis-status.json"),state);Files.writeString(stage.resolve("WARNINGS.md"),warningText(state.get("status").toString(),warnings),StandardCharsets.UTF_8);
                manifest.put("engine",ENGINE);manifest.put("analysis_status",state.get("status"));manifest.put("results_admitted",state.get("results_admitted"));manifest.put("scope",SCOPE);manifest.put("verify_replays_MACS_statistics",false);manifest.put("host_DLL_authentication",false);manifest.put("historical_whole_environment",false);json(stage.resolve("manifest.json"),manifest);
            });seal(destination);if(code[0]==0)try{verify(destination);}catch(Exception failure){code[0]=2;reject(destination,failure);}
            emit(code[0]==0?out:err,(code[0]==0?"Completed original MACS peak capture: ":code[0]==3?"SKIP3 — DEPENDENT PEAK ANALYSIS SKIPPED: ":"FAIL2 — NO PEAK RESULT ADMITTED: ")+destination);emit(err,"WARNINGS / REQUIRED ACTIONS: "+destination.resolve("WARNINGS.md")+"\n"+ACTION);return code[0];
        }catch(OutOfMemoryError failure){emit(err,"FAIL2 — NO PEAK RESULT ADMITTED: Java heap exhausted. "+ACTION);return 2;}
        catch(Exception failure){emit(err,"FAIL2 — NO PEAK RESULT ADMITTED: "+failure+"\n"+ACTION);return 2;}
    }
    static void verify(Path root)throws IOException {
        root=root.toAbsolutePath().normalize();var seal=read(root.resolve("capture-files.json"),16_000_000);keys(seal,Set.of("schema_version","authentication","files","directories"));if(integer(seal,"schema_version",0,1,1)!=1||!Boolean.FALSE.equals(seal.get("authentication")))throw new IOException("Invalid peak capture seal");
        var actual=SeuratDifferentialRuntime.footprint(root);actual.remove("capture-files.json");var pins=object(seal.get("files"),"file pins");if(!actual.keySet().equals(pins.keySet())||!directories(root).equals(strings(seal.get("directories"),"directories",1,10000)))throw new IOException("Peak capture inventory differs");for(var e:pins.entrySet())if(!FollowupSupport.hash(root.resolve(e.getKey())).equals(e.getValue()))throw new IOException("Peak capture hash mismatch: "+e.getKey());
        var state=read(root.resolve("analysis-status.json"));var manifest=read(root.resolve("manifest.json"));if(!ENGINE.equals(manifest.get("engine"))||!"completed-with-warnings".equals(state.get("status"))||!Boolean.TRUE.equals(state.get("results_admitted"))||!"completed-with-warnings".equals(manifest.get("analysis_status"))||!Boolean.TRUE.equals(manifest.get("results_admitted")))throw new IOException("Failed/skipped peak capture is not an admitted result");
        if(!SCOPE.equals(manifest.get("scope"))||!Boolean.FALSE.equals(manifest.get("verify_replays_MACS_statistics"))||!Boolean.FALSE.equals(manifest.get("host_DLL_authentication"))||!Boolean.FALSE.equals(manifest.get("historical_whole_environment")))throw new IOException("Peak scientific scope/replay/authentication claims differ");
        var original=read(root.resolve("source-request.json"));validate(original);if(!FollowupSupport.hash(root.resolve("source-request.json")).equals(manifest.get("source_request_sha256")))throw new IOException("Original peak request hash differs");var request=read(root.resolve("request.json"));if(!same(SignacPeaksInputs.capturedRequest(original),request))throw new IOException("Captured peak settings differ from original");var r=validate(request);if(!same(r,read(root.resolve("effective-request.json"))))throw new IOException("Effective peak settings differ");
        var inputs=object(manifest.get("captured_input_sha256"),"captured inputs");Set<String> names=new HashSet<>();for(Object raw:list(request.get("sources"),"sources")){var s=object(raw,"source");names.add(text(s,"fragments"));if(s.containsKey("map"))names.add(text(s,"map"));}if(request.containsKey("cell_groups"))names.add(text(request,"cell_groups"));if(!names.equals(inputs.keySet()))throw new IOException("Captured original input population differs");for(String n:names)if(!FollowupSupport.hash(root.resolve(n)).equals(inputs.get(n)))throw new IOException("Captured original input changed");
        SignacPeaksRuntime.sources(root,true);var prepared=SignacPeaksInputs.prepare(root,r,true);var binding=read(root.resolve("runtime-binding.json"),64_000_000);String home=text(binding,"home"),stage=text(manifest,"stage_at_execution");
        String parent=linux(text(manifest,"request_directory_at_execution"));if(!linux(stage).equals(stage)||!linux(home).equals(home)||!linux(text(original,"macs2_home").startsWith("/")?text(original,"macs2_home"):parent+"/"+text(original,"macs2_home")).equals(home))throw new IOException("Recorded original runtime/stage paths differ");
        if(!Boolean.FALSE.equals(binding.get("compiled_module_source_authentication"))||!Boolean.FALSE.equals(binding.get("whole_host_authentication")))throw new IOException("Unsupported source authentication claim");SignacPeaksRuntime.audit(object(binding.get("fingerprints"),"runtime fingerprints"),object(binding.get("metadata"),"runtime metadata"),home,r);
        SignacPeaksOutputs.process(root.resolve("runtime-probe/process.json"),r,List.of(home+"/bin/python","-I","-B","-X","pycache_prefix="+stage+"/unused-pycache",stage+"/source/runtime-probe.py"),List.of());if(!same(read(root.resolve("runtime-probe/process.stdout")),binding.get("metadata")))throw new IOException("Captured original runtime metadata differs");
        List<String> warnings=new ArrayList<>(List.of(SCOPE));warnings.addAll(prepared.warnings());warnings.addAll(SignacPeaksOutputs.publish(root,r,prepared,home,stage,true));if(!Files.readString(root.resolve("WARNINGS.md"),StandardCharsets.UTF_8).equals(warningText("completed-with-warnings",warnings))||!ACTION.equals(state.get("required_action"))||!Boolean.TRUE.equals(state.get("all_requested_calls_completed"))||integer(state,"requested_calls",0,1,512)!=prepared.jobs().size())throw new IOException("Required warnings or completed source population differ");
        var completed=read(root.resolve("COMPLETED.json"));if(!ENGINE.equals(completed.get("engine"))||!"completed-audited-original-peak-capture".equals(completed.get("status"))||!Boolean.TRUE.equals(completed.get("results_admitted"))||!Boolean.FALSE.equals(completed.get("statistical_replay"))||!Boolean.FALSE.equals(completed.get("authentication")))throw new IOException("Invalid peak completion scope");
        Set<String> allowed=SignacPeaksOutputs.allowedFiles(r,prepared);var withSeal=new HashSet<>(actual.keySet());withSeal.add("capture-files.json");if(!allowed.equals(withSeal))throw new IOException("Unexpected/missing complete peak capture members");Set<String> expectedDirs=new TreeSet<>(List.of("inputs","prepared","source","process","macs","runtime-probe"));for(String name:allowed){int slash=name.lastIndexOf('/');while(slash>=0){expectedDirs.add(name.substring(0,slash));slash=name.lastIndexOf('/',slash-1);}}if(!new ArrayList<>(expectedDirs).equals(directories(root)))throw new IOException("Unlisted empty/nested peak capture directory");
        LoaderOptions options=new LoaderOptions();options.setAllowDuplicateKeys(false);options.setMaxAliasesForCollections(0);options.setCodePointLimit(16_000_000);if(Files.size(root.resolve("manifest.yaml"))>16_000_000)throw new IOException("Generic manifest exceeds capacity");Map<String,Object> yaml;try(var in=Files.newBufferedReader(root.resolve("manifest.yaml"),StandardCharsets.UTF_8)){yaml=object(new Yaml(new SafeConstructor(options)).load(in),"generic manifest");}for(var e:manifest.entrySet())if(!same(e.getValue(),yaml.get(e.getKey())))throw new IOException("Generic/native manifest binding differs: "+e.getKey());var outputs=object(yaml.get("output_sha256"),"generic output hashes");var expected=new TreeMap<String,Object>(pins);expected.remove("manifest.yaml");if(!same(expected,outputs))throw new IOException("Generic transaction output hashes/population differ");
    }
    private static String linux(String path)throws IOException{if(!path.startsWith("/")||path.indexOf('\0')>=0)throw new IOException("Require recorded absolute Linux path");var parts=new ArrayList<String>();for(String part:path.split("/")){if(part.isEmpty()||part.equals("."))continue;if(part.equals("..")){if(parts.isEmpty())throw new IOException("Invalid recorded Linux path");parts.remove(parts.size()-1);}else parts.add(part);}return "/"+String.join("/",parts);}
    private static List<String> directories(Path root)throws IOException{try(var paths=Files.walk(root)){return paths.filter(p->!p.equals(root)&&Files.isDirectory(p,LinkOption.NOFOLLOW_LINKS)).map(p->root.relativize(p).toString().replace('\\','/')).sorted().toList();}}
    static void seal(Path root)throws IOException {Map<String,String> files=new TreeMap<>();for(String n:SeuratDifferentialRuntime.footprint(root).keySet())if(!n.equals("capture-files.json"))files.put(n,FollowupSupport.hash(root.resolve(n)));json(root.resolve("capture-files.json"),Map.of("schema_version",1,"authentication",false,"files",files,"directories",directories(root)));}
    private static void reject(Path root,Exception failure)throws IOException{var state=read(root.resolve("analysis-status.json"));state.put("status","FAIL2_PUBLISHED_VERIFICATION_FAILED");state.put("results_admitted",false);state.put("error",failure.toString());json(root.resolve("analysis-status.json"),state);var manifest=read(root.resolve("manifest.json"));manifest.put("analysis_status",state.get("status"));manifest.put("results_admitted",false);json(root.resolve("manifest.json"),manifest);json(root.resolve("COMPLETED.json"),Map.of("status","FAIL2_PUBLISHED_VERIFICATION_FAILED","results_admitted",false));Files.writeString(root.resolve("WARNINGS.md"),"# FAIL2 — NO PEAK RESULT ADMITTED\n\n"+failure+"\n\nRequired action: "+ACTION+"\n\n"+Files.readString(root.resolve("WARNINGS.md")),StandardCharsets.UTF_8);seal(root);}
    private static String warningText(String status,List<String> warnings){return "# ORIGINAL MACS PEAK ANALYSIS: "+status+"\n\n"+String.join("\n\n",warnings)+"\n\nRequired action: "+ACTION+"\n";}
    private static void emit(PrintStream stream,String text){stream.writeBytes((text+"\n").getBytes(StandardCharsets.UTF_8));}
}
